const original=$('Validate & Normalize').item.json;
const raw=$json?.choices?.[0]?.message?.content;
if(!raw) throw new Error('AI response content not found');
let cleaned=String(raw).trim().replace(/^```json\s*/i,'').replace(/^```\s*/,'').replace(/```$/,'').trim();
let ai;
try { ai=JSON.parse(cleaned); } catch(e) { throw new Error('AI returned invalid JSON: '+cleaned); }
const categories=['Financeiro','Técnico','Comercial','Outros'];
const priorities=['Baixa','Média','Alta','Crítica'];
const normalize=(value,allowed,fallback)=>allowed.find(v=>v.toLowerCase()===String(value??'').trim().toLowerCase()) ?? fallback;
const categoria=normalize(ai.categoria,categories,'Outros');
const prioridade=normalize(ai.prioridade,priorities,'Média');
const now=new Date();
const ticket=`SFAI-${now.getTime().toString().slice(-8)}`;
return [{json:{Ticket:ticket,Nome:original.name,Email:original.email,Empresa:original.company,Assunto:original.subject,Mensagem:original.message,Categoria:categoria,Prioridade:prioridade,Status:'Aberto',CriadoEm:now.toISOString(),Resumo:String(ai.resumo??'').trim(),MotivoIA:String(ai.motivo??'').trim()}}];

